#include <iostream>
#include <vector>
using namespace std;

vector<long long> pattern(18);
int min_moves=1e9;

void recurse(int current_moves, long long remaining_value, int position)
{
    if(current_moves > min_moves)
        return;
    if(remaining_value == 0)
    {
        min_moves = min(min_moves, current_moves);
        return;
    }
    int needed_times = remaining_value / pattern[position];
    recurse(current_moves + position * needed_times++, remaining_value - needed_times * pattern[position], position - 1);
    recurse(current_moves + needed_times * position, needed_times * pattern[position] - remaining_value, position - 1);
}

int main()
{
    long long input_value;
    cin >> input_value;
    pattern[1] = 1;
    for(int i=2; i<18; i++)
        pattern[i] = pattern[i-1] * 10 + 1;
    long long temp = input_value;
    min_moves = 1000000000;
    while(temp > 0)
    {
        for(int i=1; i<18; i++)
        {
            if(pattern[i] > temp)
            {
                min_moves += (i - 1);
                temp -= pattern[i - 1];
                break;
            }
        }
    }
    recurse(0, input_value, 16);
    cout << min_moves << endl;
}
